def decide(recipient_reputation, round_num, my_history):
    """
    Decision rule: bootstrap by donating if we have rarely donated (self‑reliance),
    then use a dynamic reputation threshold that increases with round number.
    """
    # Count how many times we have donated so far
    own_donations = sum(1 for action in my_history if action is True)

    # Bootstrap: if we donated fewer than 5 times, always donate (build trust)
    if own_donations < 5:
        return True

    # Afterwards, threshold increases gradually over time
    dynamic_threshold = min(0.3, 0.05 * (round_num - 10)) if round_num > 10 else 0.0
    return recipient_reputation > dynamic_threshold

