def decide(recipient_reputation, round_num, my_history):
    """
    Decision rule:
    - Unconditional donation in the first 5 rounds.
    - Afterwards, compute own donation rate from personal history.
          If donation rate >= 50%: be lenient (threshold = -0.1)
          Otherwise: be strict (threshold = 0.2)
    - Donate only if recipient_reputation exceeds the threshold.
    """
    # Early rounds: cooperate to build relationships
    if round_num < 5:
        return True

    # Calculate own donation rate from my_history
    total_rounds = len(my_history)
    if total_rounds == 0:
        donation_rate = 0.0
    else:
        # Assume each entry in my_history is a dict with key 'action' (string)
        donations = sum(1 for h in my_history if h['action'] == 'donate')
        donation_rate = donations / total_rounds

    # Adjust threshold based on personal generosity
    if donation_rate >= 0.5:
        threshold = -0.1   # more forgiving
    else:
        threshold = 0.2    # more demanding

    return recipient_reputation > threshold

