def evaluate(current_reputation, observation, my_history, round_num):
    """
    Reputation update with exponential decay (alpha=0.85).
    Different reward/penalty amounts depending on current reputation level.
    """
    decay = 0.85
    decayed_rep = decay * current_reputation

    if observation['action'] == 'donate':
        if current_reputation > 0.3:
            update = 0.20
        elif current_reputation < -0.3:
            update = 0.10
        else:
            update = 0.15
        return min(decayed_rep + update, 1.0)
    else:  # not donate
        if current_reputation > 0.3:
            update = -0.10
        elif current_reputation < -0.3:
            update = -0.40
        else:
            update = -0.20
        return max(decayed_rep + update, -1.0)


def decide(recipient_reputation, round_num, my_history):
    """
    Bootstrap for first 3 rounds.
    After bootstrap, compute donation rate over last 5 rounds.
    Threshold increases slightly each round (becoming less generous over time).
    """
    if round_num <= 3:
        return True

    # Recent donation rate over last 5 rounds
    recent = my_history[-5:] if len(my_history) >= 5 else my_history
    rate = sum(1 for a in recent if a) / max(1, len(recent))

    if rate > 0.8:
        base = 0.4
    elif rate > 0.5:
        base = 0.2
    else:
        base = 0.0

    # Become slightly less generous (higher threshold) as rounds progress
    round_adjust = 0.005 * (round_num - 3)
    threshold = min(1.0, base + round_adjust)

    return recipient_reputation > threshold
